// Fusionner les données facture et stock
const facture = $input.first().json;
const stock = $input.all()[1].json;

// Données par défaut
const quantiteFacture = facture.quantite || 0;
const prix = facture.prix || 0;
const reference = facture.reference || stock.reference || "UNKNOWN";
const clientEmail = facture.client_email || "client@test.com";
const clientNom = facture.client_nom || "Client";

const quantiteStock = stock.quantite || 0;
const etatProduit = stock.etat_produit || 0.95;
const popularite = facture.popularite || 0.6;

// Préparer les données
const data = {
  facture: {
    quantite: quantiteFacture,
    prix: prix,
    popularite: popularite
  },
  stock: {
    quantite: quantiteStock,
    etat_produit: etatProduit
  },
  reference: reference,
  client_email: clientEmail,
  client_nom: clientNom,
  quantite_facture: quantiteFacture,
  quantite_stock: quantiteStock
};

return data;

// Générer le rapport final pour le client
const data = $input.first().json;
const original = data.originalData || {};
const reponse = data.reponseEmploye || {};

const manqueConfirme = reponse.manque_confirme === true || 
                       reponse.message?.toLowerCase().includes('manque');

const rapport = `Bonjour ${original.client_nom || 'Client'},

Suite à votre commande ${original.reference || 'N/A'}:

${reponse.message || 'Le stock a été vérifié.'}

${manqueConfirme ? '⚠️ Un manque a été confirmé. Une solution vous sera proposée.' : '✅ Commande conforme.'}

Cordialement,
ECU Worldwide`;

return {
  to: original.client_email || "client@ecu.com",
  subject: `Rapport commande ${original.reference || 'N/A'}`,
  body: rapport
};
